function computeLocalScore(){
    var map = { never:0, occasionally:1, frequently:2, constantly:3 }, total = 0;
    for(var i=0;i<QUESTIONS.length;i++){
      var v = answers[i]; if(!v) continue;
      var k = String(v).trim().toLowerCase(); if(k in map) total += map[k];
    }
    return total;
  }

function computeLocalScore() {
    const m = { 'never': 0, 'occasionally': 2, 'frequently': 5, 'constantly': 8 };
    return answers.reduce((t, a) => t + (m[(a || 'never').trim().toLowerCase()] || 0), 0);
  }

function computeRiskScore() {
    let score = 0;
    for (let i = 0; i < QUESTIONS.length; i++) {
      const q = QUESTIONS[i];
      const ans = answers[i];
      if (q.protective) {
        if (ans === 'No') score++;
      } else {
        if (ans === 'Yes') score++;
      }
    }
    return score;
  }

